; clash_none.asm -- chapter 1: a ball on a field of grass
; generated by gen01.py
        INCLUDE "msx.inc"
        OUTPUT "clash_none.rom"
        ORG $4000
        CART_HEADER init
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; 16 KB, display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, 1          ; border colour
        VRAM_WRITE 0            ; clear all 16 KB
        ld bc, $4000
.clear: xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clear
        VRAM_WRITE $1800        ; names: 0-255 in each third
        ld c, 3
.third: xor a
.name:  out (VDP_DATA), a
        inc a
        jr nz, .name
        dec c
        jr nz, .third
        VRAM_WRITE $2000        ; colours: 0x21 everywhere
        ld bc, 6144
.col:   ld a, $21
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $1B00        ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the grass: two dots in every byte
        ld bc, 6144
        ld d, 0
grass:  ld a, d
        and 3
        ld hl, dots
        add a, l
        ld l, a
        ld a, (hl)
        out (VDP_DATA), a
        inc d
        dec bc
        ld a, b
        or c
        jr nz, grass
        ld hl, cells            ; the ball, drawn into the cells it covers
        ld c, 9
cell:   ld e, (hl)
        inc hl
        ld d, (hl)
        inc hl
        ld a, e
        out (VDP_CTRL), a
        ld a, d
        or $40
        out (VDP_CTRL), a
        ld b, 8
pixels: ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz pixels
        dec c
        jr nz, cell
        VDP_REG 1, $C0          ; display on
done:   jr done
        ALIGN 4
dots:   db $88, $22, $44, $11
cells:                          ; address, then the 8 bytes of each cell
        dw $0B78
        db $88, $22, $44, $11, $88, $22, $45, $13
        dw $0B80
        db $88, $22, $44, $11, $98, $FF, $FF, $FF
        dw $0B88
        db $88, $22, $44, $11, $88, $22, $C4, $D1
        dw $0C78
        db $8F, $27, $47, $1F, $8F, $27, $47, $17
        dw $0C80
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        dw $0C88
        db $E8, $E2, $E4, $F1, $F8, $E2, $E4, $F1
        dw $0D78
        db $8B, $23, $44, $11, $88, $22, $44, $11
        dw $0D80
        db $FF, $FF, $FF, $19, $88, $22, $44, $11
        dw $0D88
        db $C8, $A2, $44, $11, $88, $22, $44, $11
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
